#!/bin/sh
# Generated by tools/gemm_remote_leg.sh (--payload mamba). RUNS ON THE POD.
set -u
campaign_started=$(date +%s)
ROOT=/root/mojolearn
OUT=/root/gemm_leg_out
mkdir -p "$OUT"
cd "$ROOT" || exit 9
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1
export MAX_JOBS=2 CMAKE_BUILD_PARALLEL_LEVEL=2
cores=$(python3 -c 'import os; print(",".join(map(str, sorted(os.sched_getaffinity(0))[:2])))')
taskset -pc "$cores" $$ > "$OUT/cpu-affinity.log" 2>&1 || exit 9
{
  echo "vendor=nvidia"
  echo "payload=mamba"
  echo "knn_layout_only=0"
  echo "nvidia_campaign=5"
  echo "commit=34fb352f0754ba5ce281728b8bc510f992b62e08"
  echo "started=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
} > "$OUT/leg.txt"
if [ "5" = 4 ] || [ "5" = 5 ] || [ "5" = 6 ]; then
    # Keep the qualified vendor settings. CUDA pool-only overrides refused
    # small allocations in two retained attempts; its baseline used defaults.
    # HIP's default pool exceeded the external guard; its 1 GiB override passed.
    if [ "nvidia" = amd ]; then
        export MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_SIZE=1073741824
        export MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_ONLY=true
        export MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_CHUNK_PERCENT=100
        printf '%s\n' 'device_memory_pool_bytes=1073741824' 'device_memory_pool_only=true' \
            'device_memory_pool_chunk_percent=100' >> "$OUT/leg.txt"
    else
        unset MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_SIZE MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_ONLY MODULAR_DEVICE_CONTEXT_MEMORY_MANAGER_CHUNK_PERCENT
        printf '%s\n' 'device_memory_pool=qualified NVIDIA runtime defaults; external guard retained' >> "$OUT/leg.txt"
    fi
    python3 tools/training_validation_admit.py --inventory-root "$ROOT" \
        > "$OUT/source_inventory.json" || exit 9
fi
uname -a > "$OUT/uname.txt" 2>&1
nvidia-smi --query-gpu=name,driver_version --format=csv,noheader > "$OUT/gpu.txt" 2>&1 || echo "no vendor smi tool answered" >> "$OUT/gpu.txt"
{ find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs shasum -a 256 2>/dev/null || \
  find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs sha256sum ; } \
  | { shasum -a 256 2>/dev/null || sha256sum ; } \
  | awk '{print $1}' > "$OUT/source_sha256.txt"
if [ ! -x "$HOME/.pixi/bin/pixi" ] && ! command -v pixi >/dev/null 2>&1; then
  if [ "5" != 0 ] || [ "0" = 1 ]; then
    timeout -k 10 120 sh -c 'curl -fsSL --max-time 30 https://pixi.sh/install.sh | sh' > "$OUT/pixi_install.log" 2>&1
  else
    curl -fsSL https://pixi.sh/install.sh | sh > "$OUT/pixi_install.log" 2>&1
  fi
fi
PATH="$HOME/.pixi/bin:$PATH"
export PATH
if [ "5" != 0 ] || [ "0" = 1 ]; then
    if [ "5" = 5 ]; then
        # Profile 5 must install the frozen lock under the same vendor/RSS
        # supervision as the campaign. Never proceed after bootstrap failure.
        case "nvidia" in
            nvidia) pixi_guard=tools/nvidia_serial_guard.py ;;
            amd) pixi_guard=tools/amd_serial_guard.py ;;
            *) exit 9 ;;
        esac
        pixi_rc=124
        pixi_seconds=$((3000 - $(date +%s) + campaign_started))
        if [ "$pixi_seconds" -gt 600 ]; then pixi_seconds=600; fi
        if [ "$pixi_seconds" -ge 15 ]; then
            python3 "$pixi_guard" --seconds "$pixi_seconds" --rss-gib 12 -- \
                pixi install --locked > "$OUT/pixi_env.log" 2>&1
            pixi_rc=$?
        fi
        if [ "$pixi_rc" -ne 0 ]; then
            echo "pixi_install_exit=$pixi_rc" >> "$OUT/leg.txt"
            echo 'byte_lm_validation_status=NOT_STARTED_BOOTSTRAP_FAILED' >> "$OUT/leg.txt"
            : > /root/gemm_leg.done
            echo REMOTE_BODY_DONE
            exit "$pixi_rc"
        fi
    elif [ "5" = 6 ]; then
        timeout -k 10 600 pixi install --locked > "$OUT/pixi_env.log" 2>&1 || exit 9
    else
        timeout -k 10 600 pixi install > "$OUT/pixi_env.log" 2>&1
    fi
else
pixi install > "$OUT/pixi_env.log" 2>&1
fi
echo "pixi_install_exit=$?" >> "$OUT/leg.txt"
# Reuse a root-pinned retained binding; no model or compiler build in profile 6.
if [ "5" = 6 ]; then
    compact_rc=124
    case "nvidia" in nvidia) compact_vendor=cuda ;; amd) compact_vendor=hip ;; *) exit 9 ;; esac
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if [ "$work_remaining" -ge 180 ]; then
        if [ "$work_remaining" -gt 2700 ]; then work_remaining=2700; fi
        MOJOLEARN_BYTE_LM_EXPECT_VENDOR="$compact_vendor" MOJOLEARN_GPU_ARCHS="sm_89" \
        MOJOLEARN_BYTE_LM_RESUME_ACTION="head64" \
        MOJOLEARN_BYTE_LM_BASELINE_HANDOFF_SHA256="" \
        MOJOLEARN_BYTE_LM_FOREIGN_HANDOFF_SHA256="" \
        MOJOLEARN_BYTE_LM_FOREIGN_SHA256="" \
        MOJOLEARN_PYTHON="python3" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
        timeout -k 20 "$work_remaining" bash tools/byte_lm_resume_transport_serial.sh \
            "$OUT/byte-lm-resume-setup" "$work_remaining" > "$OUT/byte-lm-resume-console.log" 2>&1
        compact_rc=$?
    fi
    echo "byte_lm_resume_exit=$compact_rc" >> "$OUT/leg.txt"
    echo "scope=compact diagnostic only; final root raw-file comparison mandatory" >> "$OUT/leg.txt"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$compact_rc"
fi
# The byte LM has a separate oracle-gated workload and explicit GPU target.
if [ "5" = 5 ]; then
    byte_rc=124
    case "nvidia" in nvidia) byte_vendor=cuda ;; amd) byte_vendor=hip ;; *) exit 9 ;; esac
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if [ "$work_remaining" -ge 60 ]; then
        if [ "$work_remaining" -gt 3000 ]; then work_remaining=3000; fi
        MOJOLEARN_BYTE_LM_VALIDATION_OUT="$OUT/byte-lm-validation" \
          MOJOLEARN_BYTE_LM_EXPECT_VENDOR="$byte_vendor" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
          MOJOLEARN_GPU_ARCHS="sm_89" MOJOLEARN_BYTE_LM_VALIDATION_SECONDS="$work_remaining" \
          MOJOLEARN_PYTHON="python3" \
          timeout -k 10 "$work_remaining" bash tools/byte_lm_validation_serial.sh \
          > "$OUT/byte-lm-validation-console.log" 2>&1
        byte_rc=$?
    fi
    echo "byte_lm_validation_exit=$byte_rc" >> "$OUT/leg.txt"
    echo "gpu_archs=sm_89" >> "$OUT/leg.txt"
    echo "scope=bounded nvidia byte LM validation; no cross-vendor or performance certificate" >> "$OUT/leg.txt"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$byte_rc"
fi
# Training integration is a distinct bounded qualification, with no Apple
# execution and no inherited Mamba/UMAP performance workload.
if [ "5" = 4 ]; then
    training_rc=124
    case "nvidia" in nvidia) training_vendor=cuda ;; amd) training_vendor=hip ;; *) exit 9 ;; esac
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if [ "$work_remaining" -ge 60 ]; then
        if [ "$work_remaining" -gt 3000 ]; then work_remaining=3000; fi
        MOJOLEARN_TRAIN_VALIDATION_OUT="$OUT/training-validation" \
          MOJOLEARN_TRAIN_EXPECT_VENDOR="$training_vendor" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
          MOJOLEARN_TRAIN_VALIDATION_SECONDS="$work_remaining" \
          timeout -k 10 "$work_remaining" bash tools/training_validation_serial.sh \
          > "$OUT/training-validation-console.log" 2>&1
        training_rc=$?
    fi
    echo "training_validation_exit=$training_rc" >> "$OUT/leg.txt"
    echo "scope=bounded nvidia training integration and independent gradient checks; no cross-vendor or performance certificate" >> "$OUT/leg.txt"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$training_rc"
fi
# Targeted UMAP finish shares bootstrap and the remaining lease budget only.
# It exits before either the broader feature or sequence campaign starts.
if [ "5" = 3 ]; then
    umap_rc=124
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if [ "$work_remaining" -gt 30 ]; then
        MOJOLEARN_CAMPAIGN_OUT="$OUT/umap-finish" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
          MOJOLEARN_CAMPAIGN_SECONDS="$work_remaining" \
          timeout -k 10 "$work_remaining" bash tools/nvidia_umap_finish.sh \
          > "$OUT/umap-finish-console.log" 2>&1
        umap_rc=$?
    fi
    echo "umap_finish_exit=$umap_rc" >> "$OUT/leg.txt"
    echo "scope=UMAP targeted NVIDIA comparison and real-data quality; CPU umap-learn is quality-only; no full feature or cross-vendor certification" >> "$OUT/leg.txt"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$umap_rc"
fi
# Feature finish starts directly; do not spend its bounded lease on the
# older unrelated sequence campaign before the requested feature tests.
if [ "5" = 2 ]; then
    feature_rc=124
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if [ "$work_remaining" -gt 30 ]; then
        MOJOLEARN_CAMPAIGN_OUT="$OUT/feature-finish" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
          MOJOLEARN_CAMPAIGN_SECONDS="$work_remaining" \
          timeout -k 10 "$work_remaining" bash tools/nvidia_feature_finish.sh \
          > "$OUT/feature-finish-console.log" 2>&1
        feature_rc=$?
    fi
    echo "feature_finish_exit=$feature_rc" >> "$OUT/leg.txt"
    echo "scope=feature-finish; see per-job results, not full backward certification" >> "$OUT/leg.txt"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$feature_rc"
fi
# Layout-only reuses transport/bootstrap, not the Mamba/UMAP workload.
if [ "0" = 1 ]; then
    layout_rc=124
    work_remaining=$((3000 - $(date +%s) + campaign_started))
    if ! command -v timeout >/dev/null 2>&1; then
        layout_rc=127
        echo "timeout is required" > "$OUT/layout-console.log"
    elif [ "$work_remaining" -gt 0 ]; then
        MOJOLEARN_LAYOUT_PRICE_OUT="$OUT/layout-price" \
          timeout -k 30 "$work_remaining" bash tools/knn_layout_dispatch_price.sh \
          > "$OUT/layout-console.log" 2>&1
        layout_rc=$?
    else
        echo "shared work deadline expired" > "$OUT/layout-console.log"
    fi
    echo "layout_exit=$layout_rc" >> "$OUT/leg.txt"
    echo "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$OUT/leg.txt"
    tail -40 "$OUT/layout-console.log"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$layout_rc"
fi
# Both witnesses share one work deadline, preserving the fetch reserve.
# Refuse without timeout instead of silently running an unbounded payload.
work_started=$(date +%s)
if [ "5" != 0 ]; then work_started=$campaign_started; fi
if ! command -v timeout >/dev/null 2>&1; then
    echo "umap_identity_exit=127" >> "$OUT/leg.txt"
    echo "timeout is required for the guarded payload" > "$OUT/mamba_cert_console.log"
    cert_rc=127
else
    timeout -k 30 180 pixi run mojo run -D MOJOLEARN_NUMERIC_IDENTICAL=1 \
      -I . umap/checks/identity_check.mojo > "$OUT/umap.identity.log" 2>&1
    echo "umap_identity_exit=$?" >> "$OUT/leg.txt"
    work_remaining=$((3000 - $(date +%s) + work_started))
    if [ "$work_remaining" -gt 0 ]; then
        MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" MOJOLEARN_MAMBA_CERT_OUT="$OUT/mamba-cert" \
          MOJOLEARN_MAMBA_CERT_VENDOR="nvidia" \
          timeout -k 30 "$work_remaining" pixi run mamba-backward-cert-nvidia \
          > "$OUT/mamba_cert_console.log" 2>&1
        cert_rc=$?
    else
        echo "shared work deadline expired" > "$OUT/mamba_cert_console.log"
        cert_rc=124
    fi
fi
echo "mamba_cert_exit=$cert_rc" >> "$OUT/leg.txt"
work_remaining=$((3000 - $(date +%s) + work_started))
followup_rc=124
if [ "$work_remaining" -gt 60 ]; then
  if [ "5" != 0 ]; then
    MOJOLEARN_CAMPAIGN_OUT="$OUT/campaign" MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" \
      MOJOLEARN_CAMPAIGN_SECONDS="$work_remaining" \
      timeout -k 30 "$work_remaining" bash tools/nvidia_campaign.sh \
      > "$OUT/campaign-console.log" 2>&1
    followup_rc=$?
  elif [ "0" = 1 ]; then
    MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" MOJOLEARN_MAMBA_CERT_VENDOR="nvidia" \
      MOJOLEARN_MAMBA_CERT_PROFILE=long-sequence-v1 \
      MOJOLEARN_MAMBA_CERT_OUT="$OUT/followup/mamba-long-cert" \
      timeout -k 30 "$work_remaining" pixi run bash tools/mamba_backward_certify.sh \
      > "$OUT/followup-console.log" 2>&1
    followup_rc=$?
  else
    MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" MOJOLEARN_FOLLOWUP_OUT="$OUT/followup" MOJOLEARN_MAMBA_CERT_VENDOR="nvidia" \
      timeout -k 30 "$work_remaining" bash tools/umap_mamba_followup.sh \
      > "$OUT/followup-console.log" 2>&1
    followup_rc=$?
  fi
fi
echo "followup_exit=$followup_rc" >> "$OUT/leg.txt"
if [ "0" = 1 ]; then
  work_remaining=$((3000 - $(date +%s) + work_started))
  continued_rc=124
  if [ "$work_remaining" -gt 60 ]; then
    MOJOLEARN_COMMIT="34fb352f0754ba5ce281728b8bc510f992b62e08" MOJOLEARN_CONTINUED_OUT="$OUT/continued" \
      MOJOLEARN_CONTINUED_SECONDS="$work_remaining" \
      timeout -k 30 "$work_remaining" bash tools/continued_cert_checks.sh \
      > "$OUT/continued-console.log" 2>&1
    continued_rc=$?
  fi
  echo "continued_exit=$continued_rc" >> "$OUT/leg.txt"
fi
echo "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$OUT/leg.txt"
tail -40 "$OUT/mamba_cert_console.log"
: > /root/gemm_leg.done
echo REMOTE_BODY_DONE

